package com.kagafei.g510supercheckout;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 static class Product{String name,code,mark;int price;Product(String n,int p,String c,String m){name=n;price=p;code=c;mark=m;}}
 final Map<String,Product[]> catalog=new LinkedHashMap<>();final LinkedHashMap<String,Integer> cart=new LinkedHashMap<>();GridLayout grid;TextView cartView,subtotal,tax,total,status;EditText barcode;
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);grid=findViewById(R.id.productGrid);cartView=findViewById(R.id.cart);subtotal=findViewById(R.id.subtotal);tax=findViewById(R.id.tax);total=findViewById(R.id.total);status=findViewById(R.id.status);barcode=findViewById(R.id.barcode);
 catalog.put("食品",new Product[]{new Product("食パン",198,"4901001","BREAD"),new Product("牛乳",218,"4901002","MILK"),new Product("たまご 10個",298,"4901003","EGG"),new Product("おにぎり",138,"4901004","RICE"),new Product("カレー",258,"4901005","CURRY"),new Product("ヨーグルト",158,"4901006","YOGURT")});
 catalog.put("飲料",new Product[]{new Product("緑茶 500ml",128,"4902001","TEA"),new Product("水 2L",108,"4902002","WATER"),new Product("コーヒー",148,"4902003","COFFEE"),new Product("オレンジジュース",198,"4902004","ORANGE"),new Product("コーラ",168,"4902005","COLA"),new Product("炭酸水",118,"4902006","SODA")});
 catalog.put("青果",new Product[]{new Product("りんご",158,"4903001","APPLE"),new Product("バナナ",198,"4903002","BANANA"),new Product("みかん",398,"4903003","ORANGE"),new Product("トマト",258,"4903004","TOMATO"),new Product("キャベツ",198,"4903005","CABBAGE"),new Product("じゃがいも",298,"4903006","POTATO")});
 catalog.put("日用品",new Product[]{new Product("ティッシュ",398,"4904001","TISSUE"),new Product("洗剤",348,"4904002","SOAP"),new Product("歯ブラシ",198,"4904003","BRUSH"),new Product("ラップ",258,"4904004","WRAP"),new Product("スポンジ",128,"4904005","SPONGE"),new Product("ごみ袋",298,"4904006","BAG")});
 findViewById(R.id.tabFood).setOnClickListener(v->show("食品"));findViewById(R.id.tabDrink).setOnClickListener(v->show("飲料"));findViewById(R.id.tabProduce).setOnClickListener(v->show("青果"));findViewById(R.id.tabDaily).setOnClickListener(v->show("日用品"));findViewById(R.id.clear).setOnClickListener(v->{cart.clear();refresh();status.setText("商品を選択してください");});findViewById(R.id.scan).setOnClickListener(v->scan());findViewById(R.id.pay).setOnClickListener(v->pay());show("食品");}
 void show(String cat){grid.removeAllViews();for(Product p:catalog.get(cat)){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER);card.setPadding(8,8,8,8);card.setBackgroundColor(Color.WHITE);GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=0;lp.height=0;lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);lp.rowSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);lp.setMargins(6,6,6,6);card.setLayoutParams(lp);TextView mark=new TextView(this);mark.setText(p.mark);mark.setTextSize(22);mark.setTextColor(Color.rgb(18,59,55));mark.setTypeface(null,Typeface.BOLD);mark.setGravity(Gravity.CENTER);mark.setBackgroundColor(Color.rgb(226,238,226));card.addView(mark,new LinearLayout.LayoutParams(-1,0,1f));TextView name=new TextView(this);name.setText(p.name+"\n"+p.price+"円");name.setTextSize(17);name.setTypeface(null,Typeface.BOLD);name.setGravity(Gravity.CENTER);name.setTextColor(Color.rgb(30,45,42));card.addView(name,new LinearLayout.LayoutParams(-1,-2));Button add=new Button(this);add.setText("＋ カートに追加");add.setTextSize(14);add.setOnClickListener(v->add(p));card.addView(add,new LinearLayout.LayoutParams(-1,54));grid.addView(card);}}
 void add(Product p){cart.put(p.code,cart.getOrDefault(p.code,0)+1);status.setText(p.name+" を登録しました");refresh();}
 Product find(String code){for(Product[] ps:catalog.values())for(Product p:ps)if(p.code.equals(code))return p;return null;}
 void scan(){String c=barcode.getText().toString().trim();if(c.isEmpty()){c="4901001";barcode.setText(c);}Product p=find(c);if(p==null){new AlertDialog.Builder(this).setTitle("未登録商品").setMessage("バーコード "+c+" は登録されていません。").setPositiveButton("OK",null).show();}else add(p);}
 void refresh(){if(cart.isEmpty()){cartView.setText("商品はありません");subtotal.setText("小計 0円");tax.setText("消費税 0円");total.setText("合計 0円");return;}StringBuilder s=new StringBuilder();int sub=0;for(Map.Entry<String,Integer> e:cart.entrySet()){Product p=find(e.getKey());int line=p.price*e.getValue();sub+=line;s.append(p.name).append("  × ").append(e.getValue()).append("\n").append(line).append("円\n\n");}int tx=(int)Math.floor(sub*0.10);cartView.setText(s);subtotal.setText("小計 "+sub+"円");tax.setText("消費税(デモ10%) "+tx+"円");total.setText("合計 "+(sub+tx)+"円");}
 void pay(){if(cart.isEmpty()){status.setText("商品を登録してください");return;}final String[] m={"クレジットカード","電子マネー","QRコード","現金"};new AlertDialog.Builder(this).setTitle("お支払い方法").setItems(m,(d,w)->new AlertDialog.Builder(this).setTitle("会計完了").setMessage(m[w]+"でお支払いを受け付けました。\nレシートをお取りください。").setPositiveButton("完了",(x,y)->{cart.clear();refresh();status.setText("ありがとうございました");}).show()).show();}
}
